using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Web.Script.Serialization;
using Spine;
public static class AuditTeethMotion {
 class Loader:TextureLoader { public void Load(AtlasPage p,string s){} public void Unload(object o){} }
 public class Metric {public double[] peakSourceBounds,peakStableBounds,peakMouthBounds;public double peakBoundsIntersectionOverUnion;public string rig,clip,attachment;public int samples,flippedFrames,collapsedFrames;public double maxNonRigidResidual,peakTime,minSignedTriangleRatio=double.MaxValue,maxSignedTriangleRatio=double.MinValue,minSimilarityScale=double.MaxValue,maxSimilarityScale=0,maxRotationDegrees;}
 static SkeletonData Read(string p){return new SkeletonBinary(new Atlas(p+".atlas",new Loader())){Scale=1}.ReadSkeletonData(p+".skel");}
 static float[] FaceLocal(Skeleton s, Slot slot,MeshAttachment mesh){var v=new float[mesh.WorldVerticesLength];mesh.ComputeWorldVertices(slot,v);var f=s.FindBone("on_yuz");for(int i=0;i<v.Length;i+=2){float x,y;f.WorldToLocal(v[i],v[i+1],out x,out y);v[i]=x;v[i+1]=y;}return v;}
 static double Area(float[] v,int a,int b,int c){a*=2;b*=2;c*=2;return (v[b]-v[a])*(v[c+1]-v[a+1])-(v[b+1]-v[a+1])*(v[c]-v[a]);}
 static double[] Fit(float[] p,float[] q){int n=p.Length/2;double px=0,py=0,qx=0,qy=0;for(int i=0;i<p.Length;i+=2){px+=p[i];py+=p[i+1];qx+=q[i];qy+=q[i+1];}px/=n;py/=n;qx/=n;qy/=n;double aa=0,bb=0,denom=0;for(int i=0;i<p.Length;i+=2){double x=p[i]-px,y=p[i+1]-py;aa+=x*(q[i]-qx)+y*(q[i+1]-qy);bb+=x*(q[i+1]-qy)-y*(q[i]-qx);denom+=x*x+y*y;}aa/=denom;bb/=denom;double residual=0;for(int i=0;i<p.Length;i+=2){double x=p[i]-px,y=p[i+1]-py;double dx=aa*x-bb*y+qx-q[i],dy=bb*x+aa*y+qy-q[i+1];residual=Math.Max(residual,Math.Sqrt(dx*dx+dy*dy));}return new[]{residual,Math.Sqrt(aa*aa+bb*bb),Math.Atan2(bb,aa)*180/Math.PI,aa,bb,qx,qy,px,py};}
 static double[] Bounds(float[] v){double x0=double.MaxValue,y0=double.MaxValue,x1=double.MinValue,y1=double.MinValue;for(int i=0;i<v.Length;i+=2){x0=Math.Min(x0,v[i]);y0=Math.Min(y0,v[i+1]);x1=Math.Max(x1,v[i]);y1=Math.Max(y1,v[i+1]);}return new[]{x0,y0,x1,y1};} static double Overlap(double[] a,double[] b){double intersection=Math.Max(0,Math.Min(a[2],b[2])-Math.Max(a[0],b[0]))*Math.Max(0,Math.Min(a[3],b[3])-Math.Max(a[1],b[1]));return intersection/((a[2]-a[0])*(a[3]-a[1])+(b[2]-b[0])*(b[3]-b[1])-intersection);} public static int Main(string[] args){var metrics=new List<Metric>();var trace=new System.Text.StringBuilder("rig,clip,time,attachment,residual,similarityScale,rotation,minTriangleRatio,maxTriangleRatio\n");foreach(string rig in new[]{"King","AreaCompleted"}){var data=Read(Path.Combine(args[0],rig));var s=new Skeleton(data);s.SetToSetupPose();s.UpdateWorldTransform();var setup=new Dictionary<string,float[]>();foreach(string name in new[]{"Alt Diş","Ust Diş"}){var slot=s.FindSlot(name);setup[name]=FaceLocal(s,slot,(MeshAttachment)slot.Attachment);}foreach(var clip in data.Animations){foreach(string name in setup.Keys){var metric=new Metric{rig=rig,clip=clip.Name,attachment=name};int steps=(int)Math.Ceiling(clip.Duration*60);for(int i=0;i<=steps;i++){float time=Math.Min(clip.Duration,i/60f);s.SetToSetupPose();clip.Apply(s,0,time,false,null,1,MixBlend.Replace,MixDirection.In);s.UpdateWorldTransform();var slot=s.FindSlot(name);var mesh=slot.Attachment as MeshAttachment;if(mesh==null||slot.A<.01f||mesh.A<.01f)continue;var current=FaceLocal(s,slot,mesh);var fit=Fit(setup[name],current);double min=double.MaxValue,max=double.MinValue;for(int j=0;j<mesh.Triangles.Length;j+=3){int a=mesh.Triangles[j],b=mesh.Triangles[j+1],c=mesh.Triangles[j+2];double area=Area(setup[name],a,b,c);if(Math.Abs(area)<.001)continue;double ratio=Area(current,a,b,c)/area;min=Math.Min(min,ratio);max=Math.Max(max,ratio);}metric.samples++;if(min<-.001)metric.flippedFrames++;if(min<.1)metric.collapsedFrames++;metric.minSignedTriangleRatio=Math.Min(metric.minSignedTriangleRatio,min);metric.maxSignedTriangleRatio=Math.Max(metric.maxSignedTriangleRatio,max);metric.minSimilarityScale=Math.Min(metric.minSimilarityScale,fit[1]);metric.maxSimilarityScale=Math.Max(metric.maxSimilarityScale,fit[1]);metric.maxRotationDegrees=Math.Max(metric.maxRotationDegrees,Math.Abs(fit[2]));if(fit[0]>metric.maxNonRigidResidual){metric.maxNonRigidResidual=fit[0];metric.peakTime=time;var stable=new float[current.Length];for(int k=0;k<stable.Length;k+=2){double px=setup[name][k]-fit[7],py=setup[name][k+1]-fit[8];stable[k]=(float)(fit[3]*px-fit[4]*py+fit[5]);stable[k+1]=(float)(fit[4]*px+fit[3]*py+fit[6]);}metric.peakSourceBounds=Bounds(current);metric.peakStableBounds=Bounds(stable);metric.peakBoundsIntersectionOverUnion=Overlap(metric.peakSourceBounds,metric.peakStableBounds);var mouth=s.FindSlot("Ağız");metric.peakMouthBounds=Bounds(FaceLocal(s,mouth,(MeshAttachment)mouth.Attachment));}trace.AppendFormat(System.Globalization.CultureInfo.InvariantCulture,"{0},{1},{2:F6},{3},{4:F6},{5:F6},{6:F6},{7:F6},{8:F6}\n",rig,clip.Name,time,name,fit[0],fit[1],fit[2],min,max);}metrics.Add(metric);}}}
 Directory.CreateDirectory(args[1]);File.WriteAllText(Path.Combine(args[1],"teeth-motion-audit.json"),new JavaScriptSerializer{MaxJsonLength=int.MaxValue}.Serialize(new{method="Untouched Spine binaries, all 42 tracks at 60Hz. Best-fit orientation-preserving similarity from setup tooth mesh into animated on_yuz space quantifies non-rigid tooth deformation. Signed triangle area ratio detects folds. Metrics describe source geometry, not final visible alpha/occlusion.",records=metrics}),new System.Text.UTF8Encoding(false));File.WriteAllText(Path.Combine(args[1],"teeth-motion-60hz.csv"),trace.ToString(),new System.Text.UTF8Encoding(false));foreach(var m in metrics.OrderByDescending(r=>r.maxNonRigidResidual).Take(18))Console.WriteLine(m.rig+" "+m.clip+" "+m.attachment+" residual="+m.maxNonRigidResidual.ToString("F2")+" t="+m.peakTime.ToString("F3")+" scale="+m.minSimilarityScale.ToString("F2")+".."+m.maxSimilarityScale.ToString("F2")+" minArea="+m.minSignedTriangleRatio.ToString("F2")+" flipped="+m.flippedFrames+"/"+m.samples);return 0;}
}
